#include <IQM/hdrvdp3/srgb_quality96_runtime_double.h>
#include <vulkan_instance.h>
#include <fstream>
#include <iostream>
#include <bit>
#include <limits>
#include <cmath>
using namespace IQM::HDRVDP3;namespace fs=std::filesystem;
std::vector<double> readRow(const fs::path&p,unsigned w){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f||f.tellg()!=std::streamoff(w*w*8))throw std::runtime_error("Reference shape");std::vector<double> v(w*w),row(w*w);f.seekg(0);f.read(reinterpret_cast<char*>(v.data()),v.size()*8);for(unsigned y=0;y<w;++y)for(unsigned x=0;x<w;++x)row[y*w+x]=v[x*w+y];return row;}
int main(int argc,char**argv){try{if(argc!=4)throw std::invalid_argument("Usage: v6-runtime cpu-root fresh-output");fs::path runtime=argv[1],cpu=argv[2],out=argv[3];if(fs::exists(out)||!fs::create_directories(out))throw std::invalid_argument("Fresh output");auto model=load_srgb_quality96_runtime_double(runtime,"oled");IQM::Bin::VulkanInstance instance(true,"NVIDIA",true);SRGBQuality96GPUDouble gpu(*instance.physicalDevice(),*instance.device(),*instance.queue(),instance.queueFamilyIndex,true,model.shaders,model.projection,model.mutual,model.neighbor,model.pyramid,model.comparison);size_t words=0;auto compare=[&](auto&a,auto&b){if(a.size()!=b.size())throw std::runtime_error("Shape");for(size_t i=0;i<a.size();++i)if(std::bit_cast<uint64_t>(a[i])!=std::bit_cast<uint64_t>(b[i]))throw std::runtime_error("Comparison bits at "+std::to_string(i));words+=a.size();};const unsigned widths[]{96,96,48,24,12};
 for(std::string native:{"native","native_ramps","native_identity_v2"})for(std::string display:{"led-lcd-srgb","led-lcd-wcg","oled"}){std::vector<double> r,t;for(unsigned c=1;c<=3;++c){auto a=readRow(cpu/native/(display+"_1_conv"+std::to_string(c)+"_input.f64"),96),b=readRow(cpu/native/(display+"_2_conv"+std::to_string(c)+"_input.f64"),96);r.insert(r.end(),a.begin(),a.end());t.insert(t.end(),b.begin(),b.end());}for(unsigned b=0;b<5;++b){auto result=gpu.comparison(r,t,b),expected=readRow(cpu/native/(display+"_quality_band"+std::to_string(b+1)+"_comparison.f64"),widths[b]);compare(result,expected);std::ofstream f(out/(native+"_"+display+"_band"+std::to_string(b+1)+".f64"),std::ios::binary);f.write(reinterpret_cast<const char*>(result.data()),result.size()*8);}}
 size_t nativeWords=words;for(unsigned seed=0;seed<4;++seed){std::vector<double> r(27648,1.),t=r;for(size_t i=0;i<9216;++i){size_t k=(i%3)*9216+i;if(seed==0){double refs[]{1.,.125,1e-6,32.,1e300};r[k]=refs[(i/3)%5];double center=r[k]+r[k]*.001;t[k]=i%3==0?std::nextafter(center,0.):i%3==1?center:std::nextafter(center,std::numeric_limits<double>::infinity());}else if(seed==1){switch(i%8){case 0:r[k]=0.;t[k]=0.;break;case 1:r[k]=0.;t[k]=1.;break;case 2:r[k]=-0.;t[k]=1.;break;case 3:r[k]=std::numeric_limits<double>::min();t[k]=1e300;break;case 4:r[k]=1e300;t[k]=1e300;break;case 5:r[k]=0.;t[k]=1e-300;break;case 6:r[k]=1e300;t[k]=0.;break;default:r[k]=1e-6;t[k]=0.;}}else if(seed==2){t[k]=i%19==0?1.002:1.;}else{r[k]=(double(i%97)+.5)*.013+1e-6;t[k]=r[k]*(i%2?1.0005:1.0015);}}for(unsigned b=0;b<5;++b){auto result=gpu.comparison(r,t,b),expected=quality_comparison_double(r,t,b);compare(result,expected);}}
 unsigned rejected=0;auto reject=[&](auto action){try{action();}catch(const std::exception&){++rejected;return;}throw std::runtime_error("Invalid comparison input accepted");};std::vector<double> r(27648,1.),t=r;reject([&]{gpu.comparison(r,t,5);});reject([&]{gpu.comparison({},t,0);});for(double v:{-1.,std::numeric_limits<double>::quiet_NaN(),std::numeric_limits<double>::infinity()}){r[0]=v;reject([&]{gpu.comparison(r,t,0);});}std::ofstream(out/"PASS.txt")<<nativeWords<<" native Double comparison words exact;"<<words-nativeWords<<" control words exact;"<<rejected<<" rejection checks\n";std::cout<<words<<" comparison words exact\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
